def first_ge(sorted_values, target):
    # index of the first value >= target, or len(sorted_values)
    lo, hi = 0, len(sorted_values) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if sorted_values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo
```

